export const css = "/* ArchiMate 4 design system — generated from tokens/tokens.json. Notation colours are part of the\n   standard and are intentionally identical in light and dark canvases. */\n:root {\n  --am-common: #E5DFD3;\n  --am-strategy: #EFBD5D;\n  --am-business: #EDD779;\n  --am-application: #B0D0D9;\n  --am-technology: #BCD9AE;\n  --am-motivation: #D1BADC;\n  --am-implementation: #F1BBB7;\n  --am-stroke: #000; --am-grouping-stroke: #585858; --am-label: #000;\n  --am-canvas: #fff; --am-line: 1px; --am-font: Arial, Helvetica, 'Liberation Sans', sans-serif;\n  --am-dot: 1 1; --am-dash: 4 1;\n}\n@media (prefers-color-scheme: dark) { :root:not([data-theme='light']) { --am-canvas: #1e1f22; } }\n:root[data-theme='dark'] { --am-canvas: #1e1f22; }\n.am-diagram { background: var(--am-canvas); font-family: var(--am-font); }\n.am-diagram .am-shape { stroke: var(--am-stroke); stroke-width: var(--am-line); }\n.am-diagram .am-label { fill: var(--am-label); font-family: var(--am-font); }\n.am-diagram [data-domain='common'] { --am-fill: var(--am-common); }\n.am-diagram [data-domain='strategy'] { --am-fill: var(--am-strategy); }\n.am-diagram [data-domain='business'] { --am-fill: var(--am-business); }\n.am-diagram [data-domain='application'] { --am-fill: var(--am-application); }\n.am-diagram [data-domain='technology'] { --am-fill: var(--am-technology); }\n.am-diagram [data-domain='motivation'] { --am-fill: var(--am-motivation); }\n.am-diagram [data-domain='implementation'] { --am-fill: var(--am-implementation); }\n.am-diagram [data-type='Grouping'] .am-shape { fill: #fff; stroke: var(--am-grouping-stroke); stroke-dasharray: 6 3; }\n.am-diagram .am-shape, .am-icon .f { fill: var(--am-fill, #fff); }\n.am-icon { fill: none; stroke: var(--am-stroke); stroke-width: 1.1; stroke-linejoin: round; stroke-linecap: round; }\n.am-icon .k { fill: var(--am-stroke); stroke: none; } .am-icon .g { stroke: var(--am-grouping-stroke); stroke-dasharray: 1.2 1; }\n.am-rel { fill: none; stroke: var(--am-stroke); stroke-width: var(--am-line); }\n.am-rel--realization { stroke-dasharray: var(--am-dot); }\n.am-rel--access { stroke-dasharray: var(--am-dot); }\n.am-rel--influence { stroke-dasharray: var(--am-dash); }\n.am-rel--flow { stroke-dasharray: var(--am-dash); }\n/* Grid-card helper for documentation pages */\n.am-swatch { display:inline-block; width:1em; height:1em; border:1px solid #000; vertical-align:middle; }\n";
